"""Self-contained HTML evidence report (open offline): measured results + a live evidence-graph example."""
from __future__ import annotations
import base64, html
from pathlib import Path
from benchmarks.generators.verifybench import generate
from ml.schemas import DocumentRecord
from ml.verification.engines import system_d


def _img(p: Path): return "data:image/png;base64," + base64.b64encode(p.read_bytes()).decode()


def graph_svg(case, field="date_of_birth"):
    docs = [DocumentRecord(d["document_id"], d["kind"], d["pages"], d["version"], d["superseded"], d["supersedes"], d["metadata"]) for d in case["documents"]]
    an = system_d(docs); cl = [c for c in an.claims if c.field_name == field]
    if not cl: return "<p>No claims for field.</p>"
    W, rowh = 760, 78; H = 60 + rowh * len(cl); pos = {}
    parts = [f'<svg viewBox="0 0 {W} {H}" width="100%" role="img" aria-label="Evidence graph for {field}"><style>text{{font:12px system-ui,sans-serif;fill:currentColor}}</style>']
    ent = f"entity:person"
    parts.append(f'<rect x="590" y="{H / 2 - 24}" width="150" height="48" rx="8" fill="none" stroke="currentColor"/><text x="665" y="{H / 2 + 4}" text-anchor="middle">Entity: applicant</text>')
    for i, c in enumerate(cl):
        y = 40 + i * rowh; pos[c.claim_id] = (430, y + 20)
        d = next(d for d in docs if d.document_id == c.document_id)
        parts.append(f'<rect x="10" y="{y}" width="170" height="40" rx="8" fill="none" stroke="currentColor"/><text x="95" y="{y + 25}" text-anchor="middle">{html.escape(d.kind)}</text>')
        parts.append(f'<rect x="250" y="{y}" width="360" height="40" rx="8" fill="none" stroke="currentColor"/><text x="260" y="{y + 18}">{field}: {html.escape(c.raw_value)}</text><text x="260" y="{y + 33}" opacity=".7">page {c.source_page} · bbox {list(map(int, c.source_bbox)) if c.source_bbox else "n/a"} · OCR {c.ocr_confidence}</text>')
        parts.append(f'<line x1="180" y1="{y + 20}" x2="250" y2="{y + 20}" stroke="currentColor" opacity=".6"/><text x="190" y="{y + 14}" font-size="9" opacity=".7">EXTRACTED_FROM</text>')
        parts.append(f'<line x1="610" y1="{y + 20}" x2="590" y2="{H / 2}" stroke="currentColor" opacity=".35"/>')
    for e in an.graph.edges:
        if e["type"] in ("CONTRADICTS", "SUPPORTS") and e["source"] in pos and e["target"] in pos:
            (x1, y1), (x2, y2) = pos[e["source"]], pos[e["target"]]; col = "#c0392b" if e["type"] == "CONTRADICTS" else "#27ae60"
            parts.append(f'<path d="M{x1 + 190},{y1} C{x1 + 235},{y1} {x2 + 235},{y2} {x2 + 190},{y2}" fill="none" stroke="{col}" stroke-width="2.2" {"stroke-dasharray=\"6 4\"" if e["type"] == "CONTRADICTS" else ""}/>')
    parts.append("</svg>"); return "".join(parts)


def build_html(R, plots: Path) -> str:
    t, o = R["test"]["systems"], R["test_ood"]["systems"]
    demo = next((c for c in generate(200, 0, 7, 4) if c["scenario"] == "conflict_exact" and c["units"].get("person.date_of_birth", {}).get("label") == 1), None)
    svg = graph_svg(demo) if demo else "<p>No demo case found.</p>"
    def rows(S, names):
        r = ""
        for n in names:
            m = S[n]; f = lambda x, d=3: "n/a" if x is None else f"{x:.{d}f}"
            r += f"<tr><td>{html.escape(n)}</td><td>{f(m['precision'])}</td><td>{f(m['recall'])}</td><td>{f(m['f1'])}</td><td>{m['missed_true_contradictions']}</td><td>{m['false_alarms']}</td><td>{f(m['review_rate'])}</td><td>{f(m['expected_cost_per_unit'], 4)}</td></tr>"
        return r
    names = ["A_exact_compare", "B_independent_normalized", "D_evidence_graph", "D+LR_raw_threshold", "E_graph_calibrated_selective"]
    imgs = "".join(f'<figure><img alt="{p}" src="{_img(plots / p)}" style="max-width:100%"><figcaption>{p}</figcaption></figure>' for p in ("f1_by_system.png", "reliability.png", "risk_coverage.png", "cost_sensitivity.png", "review_budget.png") if (plots / p).exists())
    return f"""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ApprovalLens — evidence report</title>
<style>:root{{--bg:#fff;--fg:#1a1a1a;--mut:#555;--line:#ddd;--acc:#3b6ea5}}@media(prefers-color-scheme:dark){{:root{{--bg:#16181c;--fg:#e8e8e8;--mut:#aaa;--line:#333;--acc:#7fb0e6}}}}
body{{background:var(--bg);color:var(--fg);font:15px/1.55 system-ui,sans-serif;max-width:980px;margin:0 auto;padding:24px}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{border-bottom:1px solid var(--line);padding:6px 8px;text-align:left}}
.note{{border-left:4px solid var(--acc);padding:8px 14px;background:rgba(127,127,127,.08)}}h2{{margin-top:34px}}.scroll{{overflow-x:auto}}figure{{margin:12px 0}}figcaption{{color:var(--mut);font-size:12px}}</style>
<h1>ApprovalLens — evidence report</h1>
<p class="note"><b>Synthetic benchmark, simulated OCR noise.</b> Numbers below were generated by <code>scripts/reproduce_results.py</code> (seed {R['seed']}, dataset <code>{R['dataset_hash'][:12]}</code>, code <code>{R['environment']['code_sha256'][:12]}</code>). They show how each system handles the failure modes this generator injects — not real-world accuracy. Costs are assumptions. A contradiction is evidence needing review, never proof of fraud.</p>
<h2>1. A contradiction the baselines handle differently</h2>
<p>Dashed red = CONTRADICTS, green = SUPPORTS. Every node keeps its source page and region; the graph is rebuilt from stored claims.</p>{svg}
<h2>2. Held-out test</h2><div class="scroll"><table><tr><th>System</th><th>Precision</th><th>Recall (strict)</th><th>F1</th><th>Missed</th><th>False alarms</th><th>Review rate</th><th>Cost/unit</th></tr>{rows(t, names)}</table></div>
<h2>3. Unseen template</h2><div class="scroll"><table><tr><th>System</th><th>Precision</th><th>Recall (strict)</th><th>F1</th><th>Missed</th><th>False alarms</th><th>Review rate</th><th>Cost/unit</th></tr>{rows(o, names)}</table></div>
<h2>4. Plots</h2>{imgs}
<h2>5. Full tables, ablations, confidence intervals, limitations</h2><p>See <code>research/results.md</code> and <code>artifacts/metrics/results.json</code>.</p></html>"""
